    // Iterate to slow down brute force
    for (i = 0; i < 10000; i++) {
        sha256_init(&ctx);
        sha256_update(&ctx, temp, SHA256_DIGEST_LENGTH);
        sha256_update(&ctx, salt, salt_len);
        sha256_final(&ctx, temp);
    }

    memcpy(out_hash, temp, SHA256_DIGEST_LENGTH);
